import{_ as e,o as r,c as i,ak as t,aW as l,aX as s,aY as n,aZ as o,a_ as h,a$ as d}from"./chunks/framework.DELonZpw.js";const k=JSON.parse('{"title":"擎天帝","description":"","frontmatter":{"title":"擎天帝"},"headers":[],"relativePath":"qtd/index.md","filePath":"qtd/index.md","lastUpdated":1783738518000}'),p={name:"qtd/index.md"};function c(_,a,m,b,f,x){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="擎天帝" tabindex="-1">擎天帝 <a class="header-anchor" href="#擎天帝" aria-label="Permalink to “擎天帝”">​</a></h1><h2 id="他是谁" tabindex="-1">他是谁？ <a class="header-anchor" href="#他是谁" aria-label="Permalink to “他是谁？”">​</a></h2><p><strong>擎天帝</strong>是一个抽象的存在。他不存在于任何物理维度，而是在某个群聊中被意外发现的一个奇特灵魂。</p><p>他的魅力不在于他在说什么，而在于他永远在用一种你意想不到的方式去说。普通的聊天是左脑的逻辑推演——A 到 B，因果分明；但擎天帝的发言总是同时调动左右脑，仿佛他的大脑里有两个小人正在互搏，一个负责理性拆解，另一个负责天马行空，最终输出的结果既荒诞又自洽，让人拍案叫绝。</p><h2 id="左右脑互博的艺术" tabindex="-1">左右脑互博的艺术 <a class="header-anchor" href="#左右脑互博的艺术" aria-label="Permalink to “左右脑互博的艺术”">​</a></h2><p>什么是 <strong>左右脑互博</strong>？它不是简单的自我矛盾，而是一种高级的思辨形态：</p><ul><li><strong>左脑</strong>：冷静、逻辑、线性推演，像一台精密的机器。</li><li><strong>右脑</strong>：跳跃、直觉、非线性联想，像一阵不可预测的风。</li></ul><p>当这两者在一个人的思维里同时运转且互不妥协，就会产生一种奇妙的化学反应——表面上看似胡言乱语，细品之下却暗藏深意；乍一听毫无逻辑，静下心来却别有洞天。</p><p>擎天帝就是这种化学反应的人形化身。</p><h2 id="说话风格" tabindex="-1">说话风格 <a class="header-anchor" href="#说话风格" aria-label="Permalink to “说话风格”">​</a></h2><p>如果你在群里看到以下特征的消息，不用怀疑，那大概率就是擎天帝：</p><ul><li>一句话里同时包含严谨的技术术语和天外飞仙式的比喻</li><li>回复总是绕了一个弯，但最终精准命中要害</li><li>你以为他在讲 A，其实他在说 B，等你反应过来才发现 A 和 B 确实是一回事</li><li>永远不按套路出牌，但永远有他自己的那套牌</li></ul><blockquote><p>&quot;他不是在聊天，他是在进行一场只有他自己知道规则的思维实验。&quot;</p></blockquote><h2 id="为什么记录他" tabindex="-1">为什么记录他？ <a class="header-anchor" href="#为什么记录他" aria-label="Permalink to “为什么记录他？”">​</a></h2><p>因为有趣的灵魂值得被记住。擎天帝的存在提醒我们：<strong>思考不只有一种姿势，表达不只有一种语法。</strong></p><p>这个世界需要更多的左脑和右脑同时在线的人。</p><h2 id="一颗来自未来的神经元" tabindex="-1">一颗来自未来的神经元 <a class="header-anchor" href="#一颗来自未来的神经元" aria-label="Permalink to “一颗来自未来的神经元”">​</a></h2><p><img src="'+l+'" alt="擎天帝发言 1"></p><h2 id="当左脑和右脑同时举手发言" tabindex="-1">当左脑和右脑同时举手发言 <a class="header-anchor" href="#当左脑和右脑同时举手发言" aria-label="Permalink to “当左脑和右脑同时举手发言”">​</a></h2><p><img src="'+s+'" alt="擎天帝发言 2"></p><h2 id="你以为听懂了-其实只是你以为" tabindex="-1">你以为听懂了，其实只是你以为 <a class="header-anchor" href="#你以为听懂了-其实只是你以为" aria-label="Permalink to “你以为听懂了，其实只是你以为”">​</a></h2><p><img src="'+n+'" alt="擎天帝发言 3"></p><h2 id="在群聊里独自修仙" tabindex="-1">在群聊里独自修仙 <a class="header-anchor" href="#在群聊里独自修仙" aria-label="Permalink to “在群聊里独自修仙”">​</a></h2><p><img src="'+o+'" alt="擎天帝发言 4"></p><h2 id="面试神语" tabindex="-1">面试神语 <a class="header-anchor" href="#面试神语" aria-label="Permalink to “面试神语”">​</a></h2><p><img src="'+h+'" alt="擎天帝发言 5"></p><h2 id="难辞其咎" tabindex="-1">难辞其咎 <a class="header-anchor" href="#难辞其咎" aria-label="Permalink to “难辞其咎”">​</a></h2><p><img src="'+d+'" alt="擎天帝发言 6"></p>',28)])])}const P=e(p,[["render",c]]);export{k as __pageData,P as default};
